import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const ThongTinCaNhan = () => {
    // 1. KHỞI TẠO TRẠNG THÁI DỮ LIỆU
    const [isEditing, setIsEditing] = useState(false);
    const [hasData, setHasData] = useState(false);
    const [errors, setErrors] = useState({ phone: '' });

    const [formData, setFormData] = useState({
        room: '',
        name: '',
        phone: ''
    });

    // Tạo danh sách phòng từ 101 đến 905 (giống ảnh bạn gửi)
    const roomList = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let room = 1; room <= 5; room++) {
            roomList.push(`${floor}0${room}`);
        }
    }

    // 2. LOGIC LẤY DỮ LIỆU VĨNH VIỄN TỪ LOCALSTORAGE
    useEffect(() => {
        const savedData = localStorage.getItem('userProfile');
        if (savedData) {
            setFormData(JSON.parse(savedData));
            setHasData(true);
            // Cập nhật trạng thái cho trang chủ cư dân biết đã có thông tin
            localStorage.setItem('isProfileUpdated', 'true');
        }
    }, []);

    // 3. LOGIC KIỂM TRA (VALIDATE) SỐ ĐIỆN THOẠI
    const validate = () => {
        let newErrors = { phone: '' };
        const phoneRegex = /^0\d{9}$/; // Bắt đầu bằng 0 và đủ 10 số

        if (!phoneRegex.test(formData.phone)) {
            newErrors.phone = 'Sai thông tin liên hệ (Phải đủ 10 số và bắt đầu bằng số 0)';
            setErrors(newErrors);
            return false;
        }

        setErrors({ phone: '' });
        return true;
    };

    // 4. LOGIC LƯU DỮ LIỆU
    const handleSave = () => {
        if (validate()) {
            localStorage.setItem('userProfile', JSON.stringify(formData));
            localStorage.setItem('isProfileUpdated', 'true');
            setHasData(true);
            setIsEditing(false);
            alert("Lưu thông tin thành công!");
        }
    };

    return (
        <div style={containerStyle} className="glass-card">
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>👤 THÔNG TIN CÁ NHÂN</h2>
            </div>

            <div style={contentWrapperStyle}>
                <div style={mainContentStyle}>

                    {/* TRƯỜNG HỢP: CHƯA CÓ DỮ LIỆU HOẶC ĐANG CHỈNH SỬA */}
                    {(!hasData || isEditing) ? (
                        <div style={{ animation: 'fadeIn 0.3s' }}>
                            <h2 style={titleStyle}>{isEditing ? "CHỈNH SỬA THÔNG TIN" : "KHAI BÁO THÔNG TIN BAN ĐẦU"}</h2>

                            {/* Chọn số phòng (Dạng bảng như ảnh 2) */}
                            <label style={labelStyle}>Chọn số phòng:</label>
                            <div className="custom-scrollbar" style={roomGridStyle}>
                                {roomList.map(room => (
                                    <div 
                                        key={room} 
                                        onClick={() => setFormData({...formData, room})}
                                        style={{
                                            ...roomItemStyle,
                                            backgroundColor: formData.room === room ? '#8b5e5e' : '#eee',
                                            color: formData.room === room ? '#fff' : '#333'
                                        }}
                                    >
                                        {room}
                                    </div>
                                ))}
                            </div>

                            {/* Nhập tên */}
                            <div style={inputGroup}>
                                <label style={labelStyle}>Họ và tên:</label>
                                <input 
                                    style={inputStyle}
                                    value={formData.name}
                                    onChange={(e) => setFormData({...formData, name: e.target.value})}
                                    placeholder="Nhập tên đầy đủ của bạn..."
                                />
                            </div>

                            {/* Nhập SĐT với thông báo lỗi */}
                            <div style={inputGroup}>
                                <label style={labelStyle}>Số điện thoại liên hệ:</label>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                                    <input 
                                        style={{
                                            ...inputStyle,
                                            borderColor: errors.phone ? 'red' : '#ddd',
                                            color: errors.phone ? 'red' : '#333',
                                            width: '250px'
                                        }}
                                        value={formData.phone}
                                        onChange={(e) => setFormData({...formData, phone: e.target.value})}
                                        placeholder="Ví dụ: 0905123456"
                                    />
                                    {errors.phone && <span style={errorTextStyle}>{errors.phone}</span>}
                                </div>
                            </div>

                            <button onClick={handleSave} style={btnSaveStyle}>LƯU THÔNG TIN CÁ NHÂN</button>
                        </div>
                    ) : (
                        /* TRƯỜNG HỢP: ĐÃ CÓ DỮ LIỆU - CHỈ HIỂN THỊ */
                        <div style={{ animation: 'fadeIn 0.3s', textAlign: 'center', paddingTop: '40px' }}>
                            <div style={avatarCircle}>
                                {formData.name.charAt(0).toUpperCase()}
                            </div>
                            <h1 style={{ fontSize: '35px', margin: '10px 0' }}>{formData.name}</h1>
                            <p style={{ color: '#8b5e5e', fontWeight: 'bold', fontSize: '20px' }}>Phòng: {formData.room}</p>

                            <div style={displayInfoBox}>
                                <div style={infoRow}>
                                    <span>Số điện thoại:</span>
                                    <strong>{formData.phone}</strong>
                                </div>
                                <div style={infoRow}>
                                    <span>Trạng thái:</span>
                                    <span style={{ color: '#28a745', fontWeight: 'bold' }}>● Đã xác minh</span>
                                </div>
                            </div>

                            <button 
                                onClick={() => setIsEditing(true)} 
                                style={btnEditStyle}
                            >
                                THAY ĐỔI THÔNG TIN CÁ NHÂN
                            </button>
                        </div>
                    )}
                </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 6px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.1); border-radius: 10px; }
                @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
            `}</style>
        </div>
    );
};

// --- STYLES ---
const containerStyle = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', backgroundPosition: 'center', overflow: 'hidden', height: 'calc(100vh - 120px)' };
const headerStyle = { padding: '20px', background: 'rgba(0,0,0,0.2)' };
const contentWrapperStyle = { flex: 1, padding: '30px', display: 'flex', justifyContent: 'center', overflowY: 'auto' };
const mainContentStyle = { width: '100%', maxWidth: '800px', backgroundColor: '#fff', borderRadius: '30px', padding: '40px', boxShadow: '0 10px 30px rgba(0,0,0,0.1)' };

const titleStyle = { color: '#8b5e5e', borderLeft: '5px solid #8b5e5e', paddingLeft: '15px', marginBottom: '30px' };
const labelStyle = { display: 'block', fontWeight: 'bold', marginBottom: '10px', color: '#555' };
const inputGroup = { marginBottom: '25px' };
const inputStyle = { width: '100%', padding: '12px 20px', borderRadius: '12px', border: '1px solid #ddd', fontSize: '16px', outline: 'none' };

const roomGridStyle = { display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '10px', height: '180px', overflowY: 'auto', padding: '15px', background: '#f9f9f9', borderRadius: '15px', marginBottom: '25px', border: '1px solid #eee' };
const roomItemStyle = { padding: '10px', textAlign: 'center', borderRadius: '10px', cursor: 'pointer', fontWeight: 'bold', transition: '0.2s', fontSize: '14px' };

const errorTextStyle = { color: 'red', fontSize: '13px', fontWeight: 'bold' };
